pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(c));
        vm.deal(address(c), 100 ether);
        bool firstOk;
        try c.getFirstWithdrawalBonus(recipient) { firstOk = true; } catch { firstOk = false; }
        if (firstOk) {
            bool secondOk;
            try c.getFirstWithdrawalBonus(recipient) { secondOk = true; } catch { secondOk = false; }
            assertTrue(!secondOk);
        } else {
            assertTrue(true);
        }
    }
}
